INSERT INTO `patient` VALUES (28,'000064995139',NULL,'^黃宥均',NULL,'2010-01-22','F132640801','本國','男',NULL,NULL,NULL,NULL,'0911067027','leaf227227@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'葉淑華','0911067027','母',NULL,NULL,NULL,NULL,'2025-04-08 14:08:24',NULL,NULL,'帶殼海鮮,  灰塵',NULL,NULL,NULL,'主訴:全身起紅疹約7年\n現病史:自一歲起發作, 兩年前症狀最嚴重, 有看本院皮膚科, 擦類固醇藥膏,  服用中醫診所的中藥, 癢甚時服用抗組織胺, 現分布於頭皮, 耳後, 臉頰, 四肢皮膚粗糙乾燥脫屑有搔抓傷口, 影響睡眠故眠差, 納差, 二便可\n250123 臉皮膚脫皮',NULL,'靈 5\n苦\n皮炎\n三黃\n魚腥草 2GM TID*7\n黃柏 2GM TID*7',NULL,'2025-06-16 11:58:42');
