INSERT INTO `patient` VALUES (30,NULL,NULL,'康嘉興',NULL,'1988-06-08','F126773433','本國','男',NULL,NULL,NULL,NULL,'0920598667','f9221215@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-04-08 14:28:40',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑塊已三年\n現病史:24歲時準備研究所, 頭皮出現斑塊, 脫屑多. 現頭皮, 面部,背部有散在性紅斑塊, 局部脫屑, 偶搔癢. 眠差多夢易醒, 二便可\n250325 後背皮膚紅斑塊近惡化, 紅斑塊大片泛紅熱癢有屑, 皮膚乾,淡紅, 身體側腹部 指甲乾癬, 眼瞼皮膚乾癬作, 多 胃不適檢查有胃潰瘍,治療改善,偶發作,眼皮乾癢,舌苔厚,口嗅,大便次數頻',NULL,'香砂六君子湯 1GM QID*30\n溫清飲 1GM QID*30\n黃連解毒湯 3GM QID*30\n甘露消毒丹 0.7GM QID*30\n紫蘇葉 0.3GM QID*30\n苦8\n08\n三1',NULL,'2025-06-11 06:37:53');
