INSERT INTO `patient` VALUES (35,NULL,NULL,'藍紫嫣',NULL,'1984-05-22','F225940503','本國','女',NULL,NULL,NULL,NULL,'0917770742','Tzuyenlan@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-04-11 09:27:42',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:頭皮處紅色斑塊十多年\n現病史:患者國中時頭皮處出現小片紅色斑塊,  症狀自己會痊癒. 懷孕後頭皮處紅色斑塊症狀開始愈來愈嚴重, 現在主要分布在髮際處和耳朵。局部鲜红,增厚起鳞屑,, 癢感明顯, 無明顯組織液. 無指甲變形或關節疼痛. 睡眠品質改善後症狀會改善. 曾用外用類固醇治療, 但停用後症狀又復發而來求治。二便可。睡眠因照顧小孩而差。月經正常(生產後週期變正常, 以前經期較亂)\n250411肚臍皮膚紅斑塊厚',NULL,NULL,NULL,'2025-05-20 01:34:53');
