INSERT INTO `patient` VALUES (50,NULL,NULL,'沈廖鴻',NULL,'1983-09-21','F126026555','本國','男',NULL,NULL,NULL,NULL,'0981596414','hongloveyou@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-04-16 12:06:14',NULL,NULL,NULL,NULL,NULL,NULL,'2022/04/21\n主訴:頭面, 雙膝淡紅斑塊伴鱗屑13年\n現病史:乾癬病史(25歲發病), 台大H 外用類固醇藥膏治療, 因外用藥膏發胖而停用, 已6年未治療, 天氣轉變時症狀加劇. 目前病灶頭皮髮際, 眉毛, 耳朵, 鼻旁, 雙膝, 成淡紅斑塊, 鱗屑, 少搔癢. 以耳朵, 耳後髮際處最嚴重. 睡眠平, 食納平, 二便平\n250403 膝關節痛, 膝蓋皮膚乾燥,厚,白屑, 耳內,耳後頭皮病灶減少, 易餓有改善, 天氣轉變食打噴嚏, 流鼻水改善, 鼻塞少作',NULL,'溫清飲 4GM TID*30\n散腫潰堅湯 1GM TID*30\n黃連解毒湯 0.5GM TID*30\n香砂六君子湯 0.5GM TID*30',NULL,'2025-06-06 09:30:49');
INSERT INTO `patient` VALUES (51,NULL,NULL,'俞建宏',NULL,'1976-06-04','G121080176','本國','男',NULL,NULL,NULL,NULL,'0921073501','helo6564@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'徐薰芳','0953070866',NULL,NULL,NULL,NULL,NULL,'2025-04-16 12:24:49',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:全身多處紅斑塊20年\n現病史:患者20年前因為不明原因頭皮處出現紅色斑塊, 之後陸陸續續全身, 四肢, 臉部都出現紅色斑塊, 病灶處增厚起; 乾癬持平, 皮膚乾燥, 後輩皮膚紅斑塊鱗屑厚, 大片, 乾燥, 癢作, 衛教運動, 注意飲食, 不規則服藥',NULL,'0*10\n溫清飲 4GM TID*4',NULL,'2025-06-24 00:51:20');
INSERT INTO `patient` VALUES (52,NULL,NULL,'趙浚宏?',NULL,'1948-02-24','T100448954','本國','男','A',NULL,NULL,NULL,'0910063280',NULL,NULL,'新北勢淡水區坪頂路52巷10號7樓','已婚','國中','其他',NULL,NULL,'基層醫療',NULL,NULL,'蔡芸汝','0983348883','夫妻',NULL,NULL,NULL,NULL,'2025-04-16 12:28:08',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:手肘和小腿紅斑塊多年\n現病史:手肘和小腿紅斑塊多年, 頭皮也有, 小腿紅斑塊明顯, 會癢, 指甲增厚, 胃偶不適, 大便硬. 近2個月腿皮膚病灶紅斑塊紅腫加重, 乾裂, 近期檢查血糖高127, PASI13.2\n250402 小腿皮膚乾癬紅斑塊改善又作, 乾燥, 手臂皮膚天冷長新斑塊, 搔抓紅疹多, 指甲剝離仍明顯, 手背皮膚紅斑, 胃嘈雜改善, 少服中藥',NULL,'清銀*1',NULL,'2025-09-18 10:00:05');
INSERT INTO `patient` VALUES (53,NULL,NULL,'廖湐瑄?',NULL,'1969-08-29','F121201325','本國','男',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-04-16 12:45:09',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:乾癬反覆發作\n現病史:乾癬8年, TBSA 4%, 病灶位: 頭皮, 腋下, 肚臍, 龜頭, 指甲\n250401 近無新症, 皮膚乾燥, 少服中藥粉, 腹和後背皮膚紅斑減少中, 指甲乾鮮少, 飲食衛教多運動 勿甜食',NULL,'0*1\n清銀*1\n溫清飲 3GM TID*4\n香砂六君子湯 1GM TID*4',NULL,'2025-06-18 09:06:12');
INSERT INTO `patient` VALUES (54,'000002827943',NULL,'王玫玲',NULL,'1944-08-07','A202468503','本國','女',NULL,NULL,NULL,NULL,'02-29239278',NULL,NULL,'永和市永元路83巷號1樓',NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-04-16 13:57:24',NULL,NULL,NULL,NULL,NULL,NULL,'2020.12.08\n主訴:乾癬病史二十多年, 近一年加重, 耳後髮際脫屑, 淡紅和黯紅角質增厚丘疹分布於頭, 手, 腳,和乳頭\n現病史:有高血壓病史, 乾癬病史在台大診斷二十多年, 平常在部立雙和醫院皮膚科拿藥, 原本穩定控制中, 但近一年家裡忙聯絡拆修工程的事, 心煩難入眠, 且伴隨乾癬症狀加重, 於北市仁愛醫院看中醫, 服中藥後失眠改善, 淡乾癬症狀仍逐漸加重, 近半年逐漸增加, 現可見脫屑紅疹於雙側耳後髮際處(大約直徑3公分), 淡紅丘疹(約5-10個)分布於手腕到手臂外側手腕背側, 黯紅增厚丘疹(大約1-2公分)於乳頭和離散狀分佈於足背側、小腿到大腿外側與臀部外側,以上病灶皆不癢,指甲光滑無角質增厚。\n202503/28 天冷則乾癬惡化,皮膚乾燥,小腿皮膚和身體乾癬皮膚 病灶加重,,天冷血壓高110=>130mmHg,改善,身體乳房病灶減輕,排便不順改善,',NULL,'0*2\n香砂六君子湯 0.5GM TID*28\n溫清飲 3.5GM TID*28\n天麻鉤藤飲 1GM TID*28',NULL,'2025-06-27 01:34:30');
