INSERT INTO `patient` VALUES (74,'000080587645',NULL,'李璐莎',NULL,'2019-07-06','F234358237','本國','女','A',NULL,'0932025761',NULL,'0988760588','Debbychun330@gmail.com',NULL,'新北市板橋區莒光路159巷5號2樓','單身','國小','學生',NULL,NULL,'基層醫療',NULL,NULL,'李柏緯','0988760588','父',NULL,NULL,NULL,NULL,'2025-04-21 14:13:36',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:腿彎曲側紅疹有結痂二週\n現病史:皮膚組,腿彎曲側紅疹有結痂 臉頻紅疹,2019/11/15.治療,四肢屈側紅疹,膝,腳踝苔蘚化,後以西藥控制,近停用西藥,服LMD中藥,惡化,手指皮膚紅腫結痂,手腕苔蘚化嚴重,膕窩也有,流鼻水,打噴嚏作.\n250416 手腕苔蘚化嚴重厚有減輕,手指皮膚红腫結痂已無,乾燥,,膕窩紅癢輕微,流鼻水,打噴嚏減少作,鼻塞 改善,',NULL,'靈*2\n滴劑*4\n龍膽瀉肝湯 0.5GM HS*28\n芍藥甘草湯 0.5GM HS*28\n小青龍湯 1.5GM HS*28\n散腫潰堅湯 1GM HS*28',NULL,'2025-08-29 23:45:41');
INSERT INTO `patient` VALUES (75,NULL,NULL,'洪誠陽',NULL,'1969-02-02','A121786097','本國','男','O',NULL,NULL,NULL,'0937977797','windwing0232@gmail.com',NULL,'台北市 大安羅斯福路3段283巷4弄7號2樓','已婚','碩士','建築',NULL,NULL,'基層醫療',NULL,NULL,'周思綺','0932014700','夫妻',NULL,NULL,NULL,NULL,'2025-04-21 14:26:39',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:指甲剝離自20歲發作\n現病史:指甲剝離發作20多年,無疼痛,只有手指,大趾也有無皮膚病灶\n250401 手指皮膚脫皮,衛教載手套,少碰水,指甲病灶稍有改善,指甲周皮膚乾燥,不規則服藥,',NULL,NULL,NULL,'2025-07-01 00:13:48');
INSERT INTO `patient` VALUES (76,'000090153949',NULL,'魏瑞琴',NULL,'1950-12-13','F203406208','本國','女','O',NULL,NULL,NULL,'0931048998',NULL,NULL,'台北市吉林路135號','已婚','高中','餐飲業',NULL,NULL,'基層醫療',NULL,NULL,'藍清雨','0928608919','夫',NULL,NULL,NULL,NULL,'2025-04-21 15:42:14',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:雙側小腿、手肘皮膚紅斑塊反覆逾十年\n現病史:病患自述雙側小腿、手肘及前臂皮膚红斑塊反覆逾十年,皮膚色鲜红,病灶邊緣明顯,皮膚乾燥增厚,屑多,癢感稍微,水泡無,搔抓無滲组織液,指甲無異狀,關節活動正常,十幾年前曾至馬借皮膚科就診,診斷為乾癬,曾接受外用類固醇藥膏、照光治療,但效果有限,且停藥後症狀反覆難癒。曾至中醫診所使用口服科中治療,自覺症狀有改善。納可、平素眠差,與癢無關,大便每日可解,質成形,小便平順。\n250418 手肘外側皮膚紅斑塊,腳膝也有, 不太想吃中藥',NULL,'0*2',NULL,'2025-08-27 03:45:51');
