INSERT INTO `patient` VALUES (81,NULL,NULL,'謝曉惠',NULL,'1994-04-05','H224050440','本國','女',NULL,NULL,NULL,NULL,'0985892646','cristine27g@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-04-21 15:45:37',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:手掌腳掌紅斑塊8年塊七年\n現病史:病患自13歲開始出現雙手指甲變形脫落,三年前開始雙手手掌及腳掌出現紅斑塊。月經前開始長黃色小包,乾掉破裂後恢復光滑皮膚,周期約一個月。曾於西醫皮膚科接受MTX治療一個月,但紅斑變多故停藥。目前手掌、手背關節處及腳踝腳掌皮紅斑塊遍布有膿泡,BSA>5%,鱗屑多厚。12歲初經,月經週期28-30天,持續五天、色紅血塊少,無經前不適、月經來時伴輕微頭痛及乳房脹痛。眠可(12:30-8:00)。大便一日一行,成形條狀。小便平。無關節痛。口乾口渴,目前LMD皮膚科擦藥膏\n左手指前側膿包己減少,但斑塊仍厚,指甲膿包反復',NULL,'土茯苓 0.5GM QID*56\n黃連解毒湯 2.5GM QID*56\n五苓散 1GM QID*56\n龍膽瀉肝湯 2GM QID*56',NULL,'2025-06-11 06:48:44');
