INSERT INTO `patient` VALUES (89,NULL,NULL,'曾正龍',NULL,'1958-11-30','J120557232','本國','男',NULL,NULL,NULL,NULL,'0932175769','tj96666@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-04-21 15:51:27',NULL,NULL,NULL,NULL,NULL,NULL,'2019.05.10\n主訴:全身皮膚红斑塊大片\n現病史:乾癬约三十年,車禍後發生,目前生物製劑治療,仍有全身红斑塊大片,乾燥有屑\n250409 小腿皮膚病灶天氣變化則增多,皮膚病灶乾燥,暗沈,屎氣多,改善,大便稀己無,飲食控制,衛教用藥,勤擦藥,少甜食',NULL,'0*14',NULL,'2025-06-11 07:36:36');
INSERT INTO `patient` VALUES (90,NULL,NULL,'戴士凱',NULL,'2019-05-15','F135302639','本國','男',NULL,NULL,NULL,NULL,'0931396561',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'戴豐正','0931396561',NULL,NULL,NULL,NULL,NULL,'2025-04-21 15:51:53',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:全身皮炎搔抓,\n現病史:皮膚泛紅,四肢皮膚斑塊厚,搔抓病灶有滲液,皮膚泛紅\n250412 飲食不節,四肢搔抓,手肘外皮膚粗,',NULL,'苦*1',NULL,'2025-06-11 06:51:36');
INSERT INTO `patient` VALUES (91,'000060693326',NULL,'李仁富',NULL,'1982-10-29','F125721391','本國','男',NULL,NULL,NULL,NULL,'0933136317','k73kjt6t@hotmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-04-21 15:53:02',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:右腳底起疹癢甚约十年\n現病史:自當兵起右腳開始起疹癢甚,一年约會有1.2次特別嚴重特別癢,上個月有看西醫皮科,擦類固醇藥膏和服用抗组織胺治療,現已停藥,眠可,納可,排便一日2-3次偏軟。疹只零星分佈於右腳腳底,局部稍粗糙乾燥,有脫屑,天熱不一定會加重。偶起小水泡。\n250331 飲食控制,穩定無水泡作',NULL,'三*8\n苦*2',NULL,'2025-06-23 06:50:53');
INSERT INTO `patient` VALUES (92,'000080422605',NULL,'李安晨',NULL,'2017-09-28','F135083746','本國','男',NULL,NULL,NULL,NULL,'0933217136','wanghowcome@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-04-21 15:53:17',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:全身多處紅色疹數月\n現病史:皮膚炎自出生3個月發作,起先症狀較輕。昨天開始因為不明原因全身發作紅疹塊,發作於頭部(臉部/頭皮/耳後)、頭部、上肢(手肘/手腕)、下肢(大小腿/膝膕窩/足踝)、軀幹(胸/腹部/腰背部)。局部皮膚紅腫伴隨紅疹,色鲜红,無搔抓傷口,脖子有組織液滲出,皮膚(粗糙、乾燥)。夜眠可,睡眠中不自覺搔抓、醒來會抓得更厲害。曾使用西醫類固醇外用,使用後症狀改善,停藥後症狀又復發。納可。二便平。\n250331 飲食不節 皮膚乾燥,搔抓,流鼻水改善,國窩搔抓',NULL,'皮炎*10\n三*6\n香砂六 0.4GM HS*28\n甘麥大棗湯 0.4GM HS*28\n烏梅 0.3GM HS*28\n小青龍湯 1GM HS*28\n辛夷散 1GM HS*28\n十全大補湯 0.5GM HS*28\n散腫潰堅湯 0.5GM HS*28',NULL,'2025-06-23 06:51:11');
INSERT INTO `patient` VALUES (93,NULL,NULL,'陳奐丞',NULL,'2018-02-20','B125660291','本國','男',NULL,NULL,'0919581232',NULL,'0977338889','Grace5570@hotmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'林珈仱','0977338889','母',NULL,NULL,NULL,NULL,'2025-04-21 15:53:49',NULL,NULL,'海鮮',NULL,NULL,NULL,'主訴:皮膚炎自出生2個月發作\n現病史:病人母親告知自出生2個月,皮膚炎發作於頸部、四肢,以四肢最為嚴重。局部皮膚红腫,色淡紅、鮮紅交雜,有搔抓傷口,搔癢甚,乾燥脫屑,輕微苔辦化,輕微增厚。睡眠中不自覺搔抓、不會醒來。海鲜誘發皮膚症狀。曾就診西醫,診斷異位性皮膚炎,曾使用西醫類固醇、生物製劑治療,效果平。納可,眠可,二便平。晨起偶發清涕鼻子癢打噴嚏。\n250409 手指背搔抓,皮膚癢作',NULL,'皮炎*14',NULL,'2025-06-12 04:15:12');
