INSERT INTO `patient` VALUES (176,'000012519002',NULL,'林玉惇',NULL,'1984-09-07','I200011115','本國','女','O',NULL,NULL,NULL,'0963986570','eifga2000@gmail.com',NULL,'嘉義市西區國華街245號西市大樓ㄧ區16號','單身','碩士','軍公教',NULL,NULL,'基層醫療',NULL,NULL,'林尚鴻','0919898172','父女',NULL,NULL,NULL,NULL,'2025-04-29 09:59:11',NULL,NULL,NULL,NULL,NULL,NULL,'2021/04/26\n主訴:臉皮膚紅疹\n現病史:異膚病史。1年左右,雙手大小魚際肌、指縫、雙足大趾內側水泡,之後膚乾燥、脫屑,指節苔癬化、雙掌乾燥。自行塗擦靈定優,可改善。近2日項後、雙肘窩皮乾癢,伴有癢疹;雙肩頭痠痛。入睡困難,淺眠易醒。喜甜食、食後脹氣。二便平。月經不規則3個月,20日1行,量少(平素26日1行)。臉皮膚紅疹發作三日,不,下巴膿疹\n250428 自三月起,腿皮膚炎發作,癢搔抓红疹,',NULL,'三*3',NULL,'2025-12-02 01:40:23');
INSERT INTO `patient` VALUES (177,'000081599350',NULL,'張宸菲',NULL,'2018-10-17','F233884738','本國','女',NULL,NULL,NULL,NULL,'0939580309',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'朱妤2','0939580309',NULL,NULL,NULL,NULL,NULL,'2025-04-29 10:00:57',NULL,NULL,NULL,NULL,NULL,NULL,'2019/02/19\n主訴:雙臉頰、腿外側皮膚炎2個月\n現病史:皮膚炎自出生2個月發作,發作於頭部(臉部/頭皮)、上肢手臂、下肢小腿、驅幹(胸腹部/腰背部),以臉及小腿外側最為嚴重。局部皮膚紅腫,色鲜紅,有搔抓傷口,無組織液滲出,皮膚(粗糙/乾燥)。因癢夜眠差,不會醒來。未曾使用西醫類固醇外用、哺餵母乳母親有服用抗組織胺。纳可700ml/d。二便平一天一兩行。  身側腰際,皮膚乾燥,粗疹反覆,流鼻水晨作,打噴嚏,偶發\n2025/04/29 身側腰際,皮膚乾燥,粗疹反覆,流鼻水晨作,打噴嚏,偶發',NULL,'小青龍湯 0.5 GM QD*3\n香砂六君子湯 0.3GM QD*3\n甘麥大棗湯 0.4GM QD*3\n消風散 1.5GM QD*3\n烏梅 0.2GM QD*3\n蒺藜 0.2GM QD*3\n三*1',NULL,'2025-06-24 00:24:40');
INSERT INTO `patient` VALUES (178,NULL,NULL,'李家瑞',NULL,'1976-04-15','A121804634','本國','男',NULL,NULL,NULL,NULL,'0936567470','jerrylee2005@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-04-29 10:02:11',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:頭皮起紅斑脫屑己兩年\n現病史:八年前開始頭皮發小塊斑塊反覆發作,兩三年前開始加重,於髮際處出現红斑,近一年來症狀加重,红斑範圍變大,右耳內也出現紅斑,红斑界限分明,病灶處略有塗起,有片狀脫屑,伴有搔癢,睡眠差時加重。西醫診斷為頭皮乾癬,塗抹藥膏後有改善,但無法痊癒。平素晚睡(12~2點睡),納可,但常脹氣時伴隨打嗝,大便一日一行,質偏軟,沖水時會散開,小便泡沫較多。晨起鼻流清涕,打噴嚏,溫差變化大時加重·平素舌根易腫脹,扁桃腺易腫。\n250429 小腿皮膚乾紅斑塊改善緩慢,後背紅斑塊多,用藥近有改善變淡,小腿红斑塊零星乾燥少許屑, 天氣變化流鼻水少作,胃脹氣 衛教飲食後少作, 額 斑塊零星,變淡,腳踝皮膚',NULL,'小青龍湯 1GM QID*28\n溫清飲 3.5GM QID*28\n香砂六君子湯 0.5GM QID*28',NULL,'2025-06-12 00:40:58');
