INSERT INTO `patient` VALUES (207,'000076191717',NULL,'蔡丞恩',NULL,'2017-04-22','A133245305','本國','男',NULL,NULL,NULL,NULL,'0922717027',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'陳郁慧','0922717029',NULL,NULL,NULL,NULL,NULL,'2025-05-02 10:04:50',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:兩頰,耳後,前胸與四肢自三個月起紅色搔癢丘疹\n現病史:皮膚炎自出生3個月發作,發作於頭部(臉部與耳後)、上臂、兩側大腿、軀幹(胸腹部),以兩頰最為嚴重。局部皮膚红疹,色鲜紅,有搔抓傷口,偶組織液滲出,皮膚粗糙脫屑。因癢甚夜眠差,睡眠中不自覺搔抓、不會醒來。曾使用西醫類固醇外用、口服抗組織胺治療,使用後症狀改善,停藥後症狀又復發。納可。二便平。近日感冒,輕微流清涕。\n250501手肘皮膚搔抓微乾,衛教飲食 經常扣指甲減少,臉頰泛紅乾燥',NULL,'蘆*2',NULL,'2025-06-19 09:17:19');
INSERT INTO `patient` VALUES (208,NULL,NULL,'黃訓豪',NULL,'1964-11-30','H120581200','本國','男',NULL,NULL,NULL,NULL,'0921013919',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-02 10:08:47',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:乾癬發作二十二年,近五年加重\n現病史:全身皮膚紅,近飲酒加重,紅斑大片,脫皮,指甲剝離,服用MTX\n250430 小腿皮膚红斑塊 減輕 皮膚病灶癢少作指甲乾癬惡化,變形,衛教手套要戴,稍有改善, 胃脹改善,鼻涕倒流,夜間鼻塞偶作, 左手大拇指關節腫改善少作,飲食衛教,工作壓力大,衛教多飲水,運動,睡不好改善,',NULL,'溫清飲 4.5GM QID*30\n半夏瀉心湯 0.5GM QID*30\n散腫潰堅湯 1GM QID*30\n清銀*10',NULL,'2025-06-12 00:51:48');
