INSERT INTO `patient` VALUES (210,'000083576205',NULL,'譚東泰',NULL,'1963-08-11','T120097257','本國','男','O',NULL,'02-82014647',NULL,'0937644894','shang.yuh@msa.hinet.net',NULL,'新北市樹林區備內街146-7號','已婚','大學','商',NULL,NULL,'基層醫療',NULL,NULL,'高素月','0919573069','夫妻',NULL,NULL,NULL,NULL,'2025-05-02 10:14:13',NULL,NULL,NULL,NULL,NULL,NULL,'20170408\n主訴:皮膚斑塊反覆發作\n現病史:皮膚斑塊反覆约十年 分布於頭臉 軀幹 四肢 指甲,不癢。病灶暗紅中度鳞屑,邊界清楚。西醫接受過外用藥物治療。\n2025/04/30 近持平,衛教少碰水,指甲改善緩慢,皮膚作 偶發,飲食衛教少甜食後,有改善,後背 手肘红斑塊暗红病灶變平,頭皮膚改善多,腿皮紅斑塊偶長減少作',NULL,'溫清飲 6GM TID*28\n清銀*12',NULL,'2025-09-23 00:18:27');
INSERT INTO `patient` VALUES (211,NULL,NULL,'林信志',NULL,'1971-06-28','P121088963','本國','男',NULL,NULL,NULL,NULL,'0926991981','uno71@seed.net.tw',NULL,'新北 市 三峽區大 學 路131號 8樓','已婚','碩士','服務業',NULL,NULL,'基層醫療',NULL,NULL,'兂曾惠君','0926261167','妻',NULL,NULL,NULL,NULL,'2025-05-02 10:20:26',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:雙手大拇指、足跟與足底皮下起膿包已30年\n現病史:初起發作於足後跟處、隨後雙手大拇指也發作,症狀初起先在皮下或指甲下起黃綠色膿包,若破掉後皮膚乾燥粗糙,無明顯搔癢,但膿包處觸碰會有疼痛感,食用不新鲜海鲜或疲倦壓力大時症狀加重,近日雙手皮膚乾燥脫皮,大拇指指甲甲錯,無關節痛。西醫診斷膿皰性乾癬,經塗抹藥膏治療後症狀反覆。平素納可,大便一日1-2行,質平,眠可。BSA:3% PASI:7.6。\n250502 近月來惡化,,兩手拇指皮膚右拇指膿包,指甲惡化,衛教少碰水, 衛教載手套,睡眠不佳,手指脫皮膚,臉頰左側,額,眉粉刺改善,濕疹作,飲食衛教,皮膚乾粗搔抓乾裂腿皮膚乾癬改近消失,',NULL,'龍膽瀉肝湯 3GM QID*28\n黃連解毒湯 3GM QID*28\n靈*1',NULL,'2025-06-27 00:55:25');
INSERT INTO `patient` VALUES (212,NULL,NULL,'黃昱雯',NULL,'1983-11-03','C221065113','本國','女',NULL,NULL,NULL,NULL,'0972165077','emperor149@hotmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-02 10:22:24',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:頭皮紅疹搔癢反覆已3年\n現病史:後腦杓及連接頸部處頭皮紅疹搔反覆已3年,近一年半加重,皮膚色暗红,搔抓時鳞屑增多,曾就診皮膚科,診斷脂漏性皮膚炎,臉部亦有紅疹,不會搔癢及脫皮,為酒糟性皮膚炎,西醫開立外用藥膏及口服藥,亦在外院服用中藥,但效果不佳。溫度及濕度變化大時,頭皮症狀加重。LMP:3/27,每次5天,色暗紅鮮紅偶有血塊,經期時腰痠。纳可,大便難,兩三日一行,質偏硬,偶爾羊屎便,小便可,眠尚可。頭皮膚癢搔抓,\n250502 頭皮乾癬仍有,頭皮癢減輕,排便改善,眠差',NULL,'柴胡加龍骨牡蠣湯 1GM TID*28\n消風散 2.5GM TID*28\n溫清飲 2GM TID*28\n滴劑*2',NULL,'2025-06-12 00:52:29');
INSERT INTO `patient` VALUES (213,NULL,NULL,'鄭宇翔',NULL,'1988-05-05','M122281813','本國','男',NULL,NULL,NULL,NULL,'0963217991',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-02 10:24:18',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:頭皮皮膚红斑塊反覆3年左右\n現病史:頭皮,腳,上背皮膚红斑塊,指甲甲床剝離,pitting,擦藥後,有改善,仍有頭皮屑,\n250502 零星紅疹 腿零星紅斑塊減, 顳側,頭皮減輕,,指甲病灶反覆,衛教少碰水,載手套,',NULL,'溫清飲 6GM TID*20\n滴劑\n靈',NULL,'2025-06-06 09:19:39');
INSERT INTO `patient` VALUES (214,NULL,NULL,'黃碧貞',NULL,'1956-12-09','K221802186','本國','女','B',NULL,NULL,NULL,'0965597750','Gmaws@ddmf.ord.tw',NULL,'台北市北投區大業路65巷89號','未婚','專科','其他',NULL,NULL,'基層醫療',NULL,NULL,'果賢法師','0912-563-466','同門師兄弟',NULL,NULL,NULL,NULL,'2025-05-02 14:18:14',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:腳底皮膚炎红腫約6年。\n現病史:腳底皮膚红腫癢,皮膚厚,腳側搔抓红疹腫,結節,手背與腳底多處汗泡疹,分布於指缝間與甲床基部成串小水泡,結痂增厚,軀幹起疹3-4年,發作紅搔癢初起由手背蔓延至軀幹腹部到背部,外用類固醇藥膏可緩解,發作不定時\n30年前診斷有甲狀腺亢進病史,3-4年後停藥,於3-4年前復發,胃食道逆流,好發胃酸上逆感,晨起有口苦感,潮熱顏红,平時自汗多且畏風,吹風後肌肉肢節痠痛,眠可,無夜尿,纳可,便1-2次/日成形, 平時腸胃敏感易便溏',NULL,'三*12\n靈*6\n苦*6',NULL,'2025-07-16 10:54:43');
