INSERT INTO `patient` VALUES (314,'000082702497',NULL,'謝佩宸',NULL,'2016-11-11','F233646710','本國','女','B',NULL,NULL,NULL,'0979713426(媽)','jojo7f_0731@yahoo.com.tw',NULL,'桃園市中壢區龍岡路三段37巷51弄17號',NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'黃文政/謝岱諭.','0966027023(爸)','媽媽/爸爸',NULL,NULL,NULL,NULL,'2025-05-07 11:21:26',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:皮膚炎自出生3個月發作\n現病史:皮膚炎自出生3個月發作,發作於臉部.頸部.手肘.手腕大小腿 膝膕窩.足踝.胸腹部,以手肘肘窩、大腿內側、頸部最為嚴重。局部皮膚紅腫,色鮮紅, 皮膚粗糙、乾燥,輕微增厚。因癢甚夜眠差,睡眠中不自覺搔抓、不會醒來。曾使用西醫類固醇外用、口服抗組織胺治療,效果平。納可。二便平。\nIGA(3), Itching score (7) , BSA( 19.5%), EASI(9.4 )\n2025/03/22 手臂外側皮膚粗疹,腰際皮膚乾粗癢作流鼻水,鼻塞,眼癢,咳嗽,鼻涕倒流',NULL,'甘麥大棗湯 0.4GM TID*7\n小青龍湯 2GM TID*7\n清肺湯 2GM TID*7',NULL,'2025-10-03 07:53:47');
