INSERT INTO `patient` VALUES (327,'000079748459',NULL,'白美珠',NULL,'1967-10-06','F221765513','本國','女',NULL,NULL,NULL,NULL,'0934222860','rose@itai.com.tw',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-07 11:28:11',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:臉部痤瘡約數年\n現病史:臉部痤瘡約數年,曾接受西醫治療,有擦西藥,有改善,但因工作壓力大,睡眠差,易復發.納可,嚴重便秘,三天至一星期一行,質硬,不易排,有時服酵素,常晚睡,最近較不易入睡.月經規則.服藥排便改善,仍長痤瘡\n2025/05/08 更年期,潮熱躁熱仍偶發,羊屎硬秘,排便不順,服藥後有改善,,,臉部痤瘡來未再作,晚睡 眠可,有運動衛教,不規則服藥',NULL,'加味逍遙散 0.2GM TID*30\n知柏地黃丸 3.4GM TID*30\n桃核承氣湯 1.4GM TID*30\n三黃瀉心湯 1GM TID*30',NULL,'2025-06-19 09:06:23');
