INSERT INTO `patient` VALUES (396,NULL,NULL,'游孟睿',NULL,'1994-08-03','F128873598','本國','男','B',NULL,NULL,NULL,'0978862129','rui830803@gmail.com',NULL,'桃園市八德區高明里高城八街19巷39號9樓','未婚','大學','軍公教',NULL,NULL,'基層醫療',NULL,NULL,'吳麗妤','0909-235-079','母子',NULL,NULL,NULL,NULL,'2025-05-07 12:01:33',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:右小腿脛前 皮膚紅斑塊狀反覆五年,\n現病史:病人本人描述,5年多前,最初病灶在右小腿脛前,皮膚開始出現小範圍的班塊狀紅疹、搔癢,皮膚病灶區位於左耳後,左前額,背部(正中央一小區),右小腿前側,色淡紅, 病灶邊緣明顯,皮膚角質增厚,脫屑,偶有癢感,無滲組織液,洗澡後無加重,無水泡,指甲正常,四肢關節活動正常,無疼痛,病灶區以右小腿前側最為嚴重,曾(診所、署桃風濕免疫科)使用外用類固醇藥膏,抗組織胺,稍微有改善,但停藥後症狀反覆難癒。眠平,最近無發燒,納可,大便順,小便順。\n2025/05/07 額頭皮膚紅斑塊,腿皮膚紅斑塊未改善,有流鼻水多,頭皮膚癢有屑',NULL,'小青龍湯 3GM TID*28\n溫清飲 2.5GM TID*28',NULL,'2025-08-15 03:57:53');
