INSERT INTO `patient` VALUES (431,'000080302579',NULL,'許芷晴',NULL,'2019-05-13','F233246907','本國','女',NULL,NULL,NULL,NULL,'0936167432','carrie9295076@yahoo.com.tw',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-09 15:57:37',NULL,NULL,NULL,NULL,NULL,NULL,'2020/08/06\n主訴:全身丘疹散布;項後、雙肘屈側、雙踝外側乾燥疹塊 约3個月\n現病史:乾燥性疹塊自出生8個月發作於全身(臉頰無),塗乳液。109/5雙頰紅疹,皮膚科外用類固醇藥膏改善,之後胸背病毒疹發作治療後,全身紅癢疹作未治療。\n目前全身紅疹散布,腿後側粗糙,項後、雙肘屈側、雙踝外側乾燥疹塊,搔嚴重影響睡眠,搔抓後組織液滲出,偶有流血。後項、踝搔抓最嚴重。頭皮脫屑。納可。二便平。',NULL,'三*2',NULL,'2025-06-16 02:38:18');
