INSERT INTO `patient` VALUES (434,NULL,NULL,'^賴牧奇',NULL,'2016-07-18','A133313068','本國','男',NULL,NULL,'0975026070',NULL,'0911740518',NULL,NULL,'新北市板橋市仁化街42巷28號4樓',NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'母','0911740518',NULL,NULL,NULL,NULL,NULL,'2025-05-09 16:45:45',NULL,NULL,NULL,NULL,NULL,NULL,'2017.01.24\n主訴:皮膚炎自出生5個月發作\n現病史:病人母親告知自出生5個月,皮膚炎發作於臉部,起初全身紅疹多目前消退,以兩頰最為嚴重。局部皮膚紅腫,色淡紅,搔摩擦臉類及抓耳後,無明顯搔抓皮膚破損情形。因癢甚夜眠差,睡眠中不自覺搔抓。IGA(3),Itching score(7),BSA(3.5%)。曾使用西醫類固醇治療,效果平。目前擦保濕乳液控制\n250508膕膝粗疹',NULL,'靈*3',NULL,'2025-07-08 06:22:15');
INSERT INTO `patient` VALUES (435,'000087561091',NULL,'曹丞凱',NULL,'2005-04-26','A131833629','本國','男',NULL,NULL,NULL,NULL,'0933864016',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-09 16:54:31',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:脖頭皮膚紅癢班皮屑反覆已一個多月\n現病史:皮膚紅斑皮反覆已一個多月 病灶區位於肩頭胸口與四肢(膝窩肘窩)病灶區:皮膚色(鮮紅)病灶邊緣明顯 皮膚增厚 鱗屑(增多)癢感 水泡無 搔抓無組織液 指甲無異狀 關節活動正常0504曾至三總中醫科求診服中藥治療平常有擦乳液無擦固醇類軟膏皮膚症狀反覆從高一就有冬天減輕夏天天氣熱時加重熬夜加重壓力大時加重納可眠可大便一日1-2次正常 成條,用藥後改善,泛紅乾燥,結痂',NULL,'消風散 3GM TID*28\n溫清飲 1GM TID*28',NULL,'2025-06-13 08:50:52');
INSERT INTO `patient` VALUES (436,NULL,NULL,'陳浩鈞',NULL,'2015-11-03','D124007309','本國','男',NULL,NULL,NULL,NULL,'0928259306',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'王惠玲','0928259306','祖母',NULL,NULL,NULL,NULL,'2025-05-09 16:55:52',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:全身膚紅暗色癢\n現病史:出生2個月全身紅疹,發作於四肢及頭皮。目前肘內側、腕踝及頭皮膚乾燥、增厚,膝前側、肘外側搔癢嚴重,合併多處搔抓傷口。近1-2個月軀幹片狀紅疹,背部搔癢合併多處搔抓後傷口。平素怕熱,汗正常,情緒差時膚發紅、癢作。夜眠差受搔影響。食慾平,喜甜食。大便日1行 , 偶便硬 , 小便平 。\n*咳嗽、白黃色鼻涕及鼻涕倒流约5日,目前未治療。3天前腹痛、現便正常。',NULL,NULL,NULL,'2025-05-13 03:43:03');
