INSERT INTO `patient` VALUES (478,NULL,NULL,'^呂世禮',NULL,'2016-11-07','J223563001','本國','女',NULL,NULL,NULL,NULL,'0920908649',NULL,NULL,'新北市土城區中央路 四段259號11樓',NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'陳 宛 萱','0920908649','母 親',NULL,NULL,NULL,NULL,'2025-05-13 09:09:28',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:全身皮膚乾燥搔抓\n現病史:全身皮膚乾燥,額皮膚乾燥,脫屑,後腰皮膚搔抓红腫,手腕,手指濕疹作,\n250327 天熱癢疹',NULL,'靈*5',NULL,'2025-09-18 10:48:41');
INSERT INTO `patient` VALUES (479,NULL,NULL,'^鍾惠娜',NULL,'1975-08-07','F229125682','本國','女',NULL,NULL,NULL,NULL,'0922268906','b226499@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-13 09:12:05',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:手掌指間處水泡癢疹10年\n現病史:患者十年前因不明原因手掌小魚際出現紅疹水泡,後指間手腕處也出現癢疹水泡,搔抓滲出組織液,季節轉換時症狀加重。使用天然肥皂洗手症狀減輕,使用冷水沖洗後癢的症狀。曾使用外用類固醇藥膏治療,但症狀反覆。睡眠可,多夢。二便可。月經正常。\n2025/05/13月經量大,天氣變化,手指腹皮膚炎作,腳趾皮膚炎起泡熱潮濕作,衛教,手前臂皮膚粗疹,刺,癢作,大趾外側粗,乾 經常碰水,甲溝炎,減輕,無潮熱,建議CV檢查 無異常,心悸少作',NULL,'消風散 1GM TID*28\n知柏地黃丸 3GM TID*28\n仙鶴草 1GM TID*28',NULL,'2025-07-08 01:41:05');
INSERT INTO `patient` VALUES (480,NULL,NULL,'黎丞軒',NULL,'2021-02-25','F135495755','本國','男',NULL,NULL,NULL,NULL,'0919510157',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'黎國揚','0919510157',NULL,NULL,NULL,NULL,NULL,'2025-05-13 09:37:03',NULL,NULL,NULL,NULL,NULL,NULL,'2021/08/12\n主訴:前、四肢屈側红疹零星3個月\n現病史:皮膚炎自出生2個月發作臉部,於小兒科外用類固醇,但症狀反覆,天熱加劇。\n目前紅疹位於胸前、四肢屈側、後頭部,全身皮膚粗糙感。納可。二便平。\n250512大腿皮膚內側搔抓癢疹,手臂癢,',NULL,'皮炎*7\n滴劑*3\n0*4',NULL,'2025-06-16 02:52:35');
INSERT INTO `patient` VALUES (481,'000076623105',NULL,'王麒凱',NULL,'1978-10-16','N123246819','本國','男','B',NULL,NULL,NULL,'0953053250','t75_machinegun@yahoo.com.tw',NULL,'彰化市永安街115號','單身','碩士','商',NULL,NULL,'基層醫療',NULL,NULL,'林靜儀','0922929887','朋友',NULL,NULL,NULL,NULL,'2025-05-13 09:44:06',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:全身多處紅色斑塊8年\n現病史:患者8年前開始臉部出現紅色斑塊,伴隨關節疼痛,診斷為乾性關節炎。經皮膚科MTX治療後症狀幾乎痊癒,但兩年多前赴大陸工作,因壓力大、應酬喝酒,飲食辛辣而復\n發。現臉、頭皮、身體軀幹和四肢都出現紅色斑塊。皮膚增厚起鳞屑,癢感甚,搔抓易出血。指甲凹陷,左膝關節疼痛。飲食可。便秘,大便2-3日一行,便硬難解。小便可。睡眠差,\n不易入睡,有時因工作關係睡眠不足。感冒咳嗽。\n2025/05/12 蛋白尿',NULL,'清銀*1',NULL,'2025-11-22 03:35:29');
INSERT INTO `patient` VALUES (482,'000089373085',NULL,'洪鏡淯',NULL,'2001-01-27','F800187986','本國','男',NULL,NULL,NULL,NULL,'0972018013',NULL,NULL,'新北市新店區復興路17號3樓4號房',NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-13 09:47:32',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:身多處紅斑塊反覆發一年餘\n現病史:皮膚炎自一年半前發作,發作於頭部(面部/頭皮)、上肢(手臂)、下肢(大小腿/臀部)、軀幹(胸部/腰背部),以小腿最為嚴重。局部皮膚紅斑,色鲜紅,有搔抓傷口,有組織液滲\n出,皮膚乾燥暗沈。夜眠可,睡眠中不自覺搔抓、不會醒來。曾使用西醫類固醇外用,中藥藥物、藥膏洽療,使用後症狀改善,停藥後症狀又復發。納可,偶腹痛腹瀉,偶發食道痙攣,胃氣上逆。大便日一行,成形質可,小便偶色偏茶色。\n現狀 大腿内側搔抓改善,病灶暗沈,反胃作改善,臉痤瘡作,腳踝濕疹塊作改善,小腿新長红疹,\n2025/05/12 手指縫皮膚皮膚炎',NULL,'靈*1\npast:\n消風散 3.8GM TID*14\n龍膽瀉肝湯 1 GMTID*14\n黃連解毒湯 0.6GM TID*14\n半夏瀉心湯 0.2GM TID*14\n白鮮皮 0.4GM TID*14',NULL,'2025-09-25 10:06:01');
INSERT INTO `patient` VALUES (483,NULL,NULL,'沈妘',NULL,'2021-11-11','J223751930','本國','女',NULL,NULL,NULL,NULL,'0920021679','yuenguo02@gmail.com',NULL,'新北市三重區元信一街135號4樓',NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'郭恩羽','0920021679','媽媽',NULL,NULL,NULL,NULL,'2025-05-13 09:53:29',NULL,NULL,NULL,NULL,NULL,NULL,'2023/03/15\n主訴:全身皮膚搔抓\n現病史:頭皮癢,有屑,後背红疹,臉皮膚粗疹,臀部红疹\n2025/03/03 膕窩搔抓嚴重改善,眼癢',NULL,'靈*3\n三*1\n皮炎*10',NULL,'2025-11-04 02:02:47');
