INSERT INTO `patient` VALUES (494,'000088660182',NULL,'張茗媗',NULL,'2019-04-13','C221884350','本國','女',NULL,NULL,'0982172412',NULL,'0958267761',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'母','0982172412',NULL,NULL,NULL,NULL,NULL,'2025-05-13 11:59:32',NULL,NULL,'蝦子',NULL,NULL,NULL,'2025/04/24\n主訴:皮膚炎自出生6-7個月發作\n現病史:病人母親告知自出生6-7個月,皮膚炎發作於雙腿、雙手、膝膕、足踝,以雙腿足踝最為嚴重。局部皮膚紅腫,色淡紅/鮮紅夾雜,有搔抓傷口,部份滲組織液,搔癢甚, 輕微苔癬化,輕微增厚。因癢甚夜眠差,睡眠中不自覺搔抓、不會醒來。曾至皮膚科就診,診斷異位性皮膚炎,曾使用西醫類固醇、口服抗組織胺治療,亦至中醫就診,效果平。目前有感冒症狀逾一周,咳嗽有痰晨起鼻子搔癢流鼻水,納可。二便1-2日一行,小便平。\n2025/05/08 大腿內側皮膚炎,紅腫有傷口,咳嗽頻作',NULL,'小青龍湯 1.5GM TID*14\n清肺湯 1.5GM TID*14\n定喘湯 1GM TID*14\n靈*1',NULL,'2025-06-16 02:57:34');
INSERT INTO `patient` VALUES (495,NULL,NULL,'呂彥鋐?',NULL,'2021-01-23','A133903026','本國','男',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-13 12:02:13',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:皮膚癢搔抓反覆\n現病史:手指背皮膚搔抓苔蘚化粗,治療反覆,全身皮膚搔抓,膝腳苔蘚化粗\n2025/04/24脖項皮膚乾燥,紅疹,後背皮膚乾燥粗疹,臉皮乾燥泛红改善,白天搔抓減少,手肘內搔抓傷口減少,',NULL,NULL,NULL,'2025-06-18 09:27:26');
