INSERT INTO `patient` VALUES (524,'000060277823',NULL,'徐涵齡',NULL,'1970-01-24','A222424847','本國','女',NULL,NULL,NULL,NULL,'0932015222',NULL,NULL,'台北市萬華區興寧街66巷22弄20號3樓',NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-15 12:52:06',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:皮膚紅疹搔癢約10年\n現病史:皮膚紅疹搔癢約10年,去年11月開始加重。發作於前手臂.大小腿。局部皮紅疹,色淡紅,有搔抓傷口,搔癢甚,皮膚乾燥,輕微苔蘚化。因癢甚夜眠差。曾使用西醫類固醇外用、口服抗組織胺治療,效果平。納可。排便平。胃泛酸。右膝關節炎腫痛 , 改善\n2025/05/01 仍有胃泛酸作.',NULL,'香砂六君子湯 3GM TID*14\n養心湯 3GM HS*14\n小青龍湯 1GM TID*14\n半夏瀉心湯 1GM HS*14\n散腫潰堅湯 2GM HS*14\n辛夷散 2GM TID*14',NULL,'2025-07-28 10:51:49');
