INSERT INTO `patient` VALUES (540,'000004456343',NULL,'黃美娟',NULL,'1953-12-11','J200360842','本國','女','B',NULL,'035409458',NULL,'0933022926',NULL,NULL,'新竹市武陵路73巷78號2樓',NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,'黃美砡','0933022926','姊妹',NULL,NULL,NULL,NULL,'2025-05-15 16:00:47',NULL,NULL,NULL,NULL,NULL,NULL,'2017.03.20\n主 訴 :乾癬復發\n現病史:皮膚紅色斑塊約10多年。位於手臂、大腿小腿、腰背部。BSA2.5%。色淡红,增厚,脫屑,圓形,不會搔癢。2017/03/20 PASI:3.5 BSA:1.3% 本治療改善,近飲食不節又作,頭皮屑多,頭皮紅斑塊,,四肢皮膚紅斑塊,耳內,皮下出血,\n2025/05/13 指甲乾癬近惡化,手掌皮膚乾燥持續改善,頭皮紅斑塊改善,頭皮頭髮有新長,後項皮膚乾癬癢,紅疹,後背 腿皮紅斑塊 減輕中,頭皮屑多減少,四肢皮膚紅斑塊減少\n内有屑少,',NULL,NULL,NULL,'2025-07-23 00:33:59');
INSERT INTO `patient` VALUES (541,NULL,NULL,'董寶釵',NULL,'1954-10-30','J200561447','本國','女',NULL,NULL,NULL,NULL,'0988123868',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-15 16:07:48',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:下肢紅斑塊,水泡约5年\n現病史:下肢紅斑塊,水泡約5年,會癢,有脫屑,曾接受馬偕醫院切片檢查確認為乾癬,HLA B27+, 曾接受擦藥及照光治療,但效果有限,指甲變形納可,便秘,羊屎便,一天一行.眠差易醒-停經約十年. 臀有紅疹,疑帶狀泡疹, \n2025/05/13 穩定,胃悶痛偶作,胃嘈雜 胃痞悶脹少,,唇乾口乾改善,鼻孔乾燥不適已無 手指甲病灶疼痛作 衛教少碰水,載手套 已少作, 腿皮膚乾響病灶色素斑,天冷高血壓稍高, SBP 140mmHg,排便可',NULL,NULL,NULL,'2025-06-12 04:25:54');
INSERT INTO `patient` VALUES (542,NULL,NULL,'楊忠敏',NULL,'1967-06-25','F121358025','本國','男',NULL,NULL,NULL,NULL,'0910469000',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-15 16:13:29',NULL,NULL,NULL,NULL,NULL,NULL,'主訴 : 後背和大腿紅斑塊多 ,\n現病史:十年前始發開始 後腦勺局部一小塊乾癬之後範圍擴大至全頭皮 反覆發作,之後手肘、小腿後側,膝蓋也發出病灶,紅色斑塊,局部粗糙增厚,有多處抓傷口,2018年才開始延伸至軀幹、腰背部大片紅疹,病情反覆,跑過多家醫院診所(黃.憲等),藥膏(Xamiol),未曾口服西藥,只有口服中藥,但停藥皆復發。誤認磨去死皮再擦藥吸收效果佳。\n2025/05/13 持續改善中,左手臂手肘病灶厚減輕,腿皮紅斑塊 減少,後下背病灶红斑塊大片 搔癢,,衛教飲食,指導用藥,服用高血壓,高血脂藥物',NULL,'溫清飲 4GM TID*28\n黃連解毒湯 2GM TID*28\n清銀*4',NULL,'2025-06-23 08:17:56');
INSERT INTO `patient` VALUES (543,NULL,NULL,'何明源',NULL,'1966-09-17','C120504039','本國','男',NULL,NULL,NULL,NULL,'0933077970',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-15 16:18:03',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:手肘和腳踝關痛\n現病史:患者從30多年開始手開始出現紅色斑塊,現頭皮、背部、四肢都出現紅色斑塊,邊缘清楚,增厚起鳞屑。掌指關節腫痛,額皮膚紅斑塊零星,\n本治療改善,近又作,臀部皮膚病灶大片,手肘和腳踝關痛\n2025/05/13 近胃漬瘍,便血作 頭皮、背部、四肢 皮膚紅色斑塊減少,手肘和腳踝關痛減輕,服藥後口乾仍有,飲食衛教,口嗅 有改善,',NULL,NULL,NULL,'2025-06-11 00:13:53');
INSERT INTO `patient` VALUES (544,NULL,NULL,'^余瑞珠',NULL,'1969-02-26','P220781725','本國','女','O',NULL,NULL,NULL,'0903638007',NULL,NULL,'新北市蘆洲區信義路266巷24弄8號5樓','已婚','國小','退休',NULL,NULL,'基層醫療',NULL,NULL,'丁和興','0958905786','夫妻',NULL,NULL,NULL,NULL,'2025-05-15 16:22:08',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:頭皮與皮膚斑塊反覆十多年\n病史:頭皮與皮膚斑塊,頭皮斑塊色淡紅稍有鱗屑,下肢斑塊色深紅帶明顯鱗屑。曾至台北市立聯合醫院昆明院區中醫科就診,療效不好。尚未至皮膚科就診(怕類固醇)。病灶癢,冬天時加重,但夜間不加重。無其他明顯加重或緩解因子。指甲變型。\n眠差易醒,無胃悶胃食道逆流,無胸悶心悸,大便一日一行成條,無口乾渴。個性較急。\n2025/05/13 口苦近嚴重,夜間口乾減輕,飲食不節,胃嘈雜 胃泛酸作 衛教飲食,有改善  小腿後側病灶紅斑塊結節,疤痕暗沉,,指甲乾癬作,天氣變化皮膚癢作,少有頭皮膚红斑塊, 壓力大,頭皮屑作,',NULL,'香砂六君子湯 1GM TID*28\n溫清飲 1GM TID*28\n小柴胡湯(甲) 2GM TID*28\n0*1',NULL,'2025-07-08 06:09:34');
INSERT INTO `patient` VALUES (545,NULL,NULL,'劉科良',NULL,'1987-06-17','J122085257','本國','男',NULL,NULL,NULL,NULL,'0915667378',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-15 16:41:05',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑塊约三年反覆,\n現病史:皮膚紅斑塊约三年反覆,目前病灶位頭皮,小腿紅斑塊多,易胃脹氣,多夢\n2025/05/14 近日手指關節痛作,小腿外側皮膚紅斑塊乾燥,紅,仍大片,胃脹已無,眠可,指導包敷用藥',NULL,'散腫潰堅湯 1GM TID*28\n黃連解毒湯 2GM TID*28\n當歸拈痛湯 3GM TID*28\n0*5',NULL,'2025-06-13 08:30:19');
INSERT INTO `patient` VALUES (546,NULL,NULL,'陳郁如*',NULL,'1968-12-13','F221805469','本國','女',NULL,NULL,NULL,NULL,'0930751635','midokichen@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-15 16:44:51',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:腹部皮膚有長癤子\n現病史:腹和腋下有刺痛癤子,乾癬病灶改善,但自覺皮膚較乾燥不適。約一週前開始陰道分泌物增,偶有血絲,腰痠明顯·納可,眠可,二便平。白帶減少\n2025/05/14 頭皮病灶惡化,後背红疹塊,紅腫,,皮膚易癢作未改善,,服DM(Hb1Ac 6.5,ac 124),高血壓藥中,脂肪肝 高血脂服西藥不適,控制不佳,壓力大,乾癬惡化,流汗病灶癢, 夜間作,心情不佳,頭皮膚病灶增大,乾燥,癢,後枕部頭皮癢,搔抓有疹塊,流鼻水咽有痰多,',NULL,'溫清飲 3GM TID*30\n黃連解毒湯  3GM TID*30\n紅麴(壽美降脂一號)每 .. 1PC BID*30',NULL,'2025-06-16 03:39:43');
INSERT INTO `patient` VALUES (547,NULL,NULL,'黃星羽',NULL,'2024-10-28','H227236479','本國','女',NULL,NULL,NULL,NULL,'0927966178',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-15 16:47:02',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:全身皮膚泛紅乾燥\n現病史:臉頰紅疹,胸腹紅疹大片,股溝红疹,口水疹多,鼻塞嚴重\n2025./05/14 近穩定少作,頭皮搔抓減少,口水多減少,臉红疹 乾燥改善,身體皮膚丘疹減少,|',NULL,NULL,NULL,'2025-05-20 06:57:22');
INSERT INTO `patient` VALUES (548,NULL,NULL,'江明城',NULL,'1977-07-29','Q122602682','本國','男',NULL,NULL,NULL,NULL,'0920363616',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-15 16:48:55',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:四肢红斑塊及丘疹反覆7年\n現病史:患者7年前開始發現四肢 出現丘疹及红斑塊,皮膚科診斷乾癬 接受外用立類固醇仍反覆發作,曾於彰化玉衡中醫接受口服及外用藥治療能改善。107/01開始四肢紅斑塊又作,\n2025/05/14 小腿皮膚,零星红斑塊暗红,乾厚,不規則服藥,乾癬 少癢,眠可,鼻涕倒流,減輕',NULL,'溫清飲 5GM BID*7\n小青龍湯 1GM BID*7\n0*1',NULL,'2025-06-16 05:36:45');
