INSERT INTO `patient` VALUES (550,'000081596516',NULL,'林芯妤',NULL,'2020-02-01','F233921549','本國','女',NULL,NULL,NULL,NULL,'0952370911',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-16 13:16:36',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:手掌腳掌自出生易脫皮 Peeling of hands and feet\n現病史:手掌腳掌自出生,泛红,易脫皮,偶癢作.Keratolysis exfoliativa of palms\n2025/05/16 天熱,腳掌皮膚易脫皮作',NULL,'黃柏 3GM QD*3\n苦參根 3GM QD*3\n三*1\n0*1',NULL,'2025-06-13 08:29:34');
INSERT INTO `patient` VALUES (551,'000074233685',NULL,'周芯羽',NULL,'2016-03-15','A232505091','本國','女',NULL,NULL,NULL,NULL,'0912525235',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-16 13:44:27',NULL,NULL,NULL,NULL,NULL,NULL,'現病史:109/2於頸部膚紅斑片,曾於皮膚科診斷:atopic dermatitis.外用類固醇及口服藥物可稍微改善,但停藥後症狀。目前全身紅斑片、乾癢伴有丘疹,髮際結節脫屑,雙臉頰、耳垂、腕踝膚脫皮,軀幹、臀腿部淡红斑散布,膝膕乾裂,苔蘚化,乾癢嚴重,影響睡眠。食纳平。二便平\n近3個月變得少汗、怕冷,氣温變化常打噴嚏、流鼻水,咳嗽。*服治療皮膚中藥>1年(十味敗毒散、當歸飲子、白鲜皮、地膚子、龍膽瀉肝湯)\n2025/05/15 小腿皮膚搔抓红疹,口唇乾燥改善',NULL,'三*8\n0*5',NULL,'2025-06-16 03:47:44');
INSERT INTO `patient` VALUES (552,'000086285071',NULL,'劉筱丰',NULL,'1982-08-26','A280002538','本國','女',NULL,NULL,NULL,NULL,'0983177466',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-16 13:59:43',NULL,NULL,'塵螨、蛋奶類',NULL,NULL,NULL,'20240311\n主訴:皮膚炎自2022年發作\n現病史:皮膚炎自2022年發作於後頸部,懷疑手機背繩過敏,接觸部位起初紅疹發,而後蔓延整片,耳後脫屑狀。2023年6月於英國時,手肘亦發紅疹,但以頸部最為嚴重。局部皮膚紅腫,色鲜红,搔癢感偶發,以病灶周圍癢感甚,有些許搔抓傷口,搔抓時部份滲組織液,手肘、耳後輕微苔蘚化,輕微增厚。因搔癢影響睡眠,睡眠中不自覺搔抓、會醒來。一年前曾至皮膚科就診,曾使用西醫類固醇藥膏治療,效果尚可。目前已停用西醫藥物。曾檢驗過敏原,塵螨、蛋奶類輕微。LMP:3/4,週期40天左右,每次來4天,無血塊,色暗红,無經痛。納可·大便兩三日一行,硬,成條。\n2025/05/15 後頸皮膚 有紅腫 乾燥有屑,頭皮膚有斑塊,鳞屑,髮際皮膚紅斑塊,',NULL,'滴劑*1\npast:\n消風散 3.5GM TID*14\n石膏 0.5GM TID*14\n生地黃 0.5GM TID*14\n桃核承氣湯 0.3GM TID*14\n木香檳榔丸 0.5GM TID*14\n枳實 0.4GM TID*14\n厚朴 0.3GM TID*14',NULL,'2025-06-16 03:50:01');
