INSERT INTO `patient` VALUES (607,NULL,NULL,'周彥均',NULL,'2017-01-29','H126761926','本國','男',NULL,NULL,NULL,NULL,'0958030875','alice.mandy12@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-19 15:37:12',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:皮膚炎自出生發作\n現病史:皮膚炎自出生兩周發作,頭皮診斷為脂漏性皮膚炎(西藥控制中,偶起白色脫屑)現病灶發作於頭頸部、上肢(手肘/手脫)、下肢(大小腿/膝膕窩/足踝)、軀幹(胸腹部、頭皮/面部最為嚴重。8/12腸病毒後皮膚病灶加重.局部皮膚紅腫且有紅疹,色淡红,有搔抓傷口,搔抓完乾燥,無组織液滲出,皮膚略粗糙。因癢甚夜眠差,睡眠中不自覺搔抓使用西醫類固醇(皮質醇/Elomet onit./Fluticosone)外用、口服抗组織胺(勝克敏),平時塗抹乳液,停藥後復發。納可。二便平。\n2025/05/17 眼睛周內',NULL,'0*3\n滴劑*2',NULL,'2025-06-16 04:12:32');
