INSERT INTO `patient` VALUES (676,NULL,NULL,'廖源順',NULL,'1964-02-14','B120635912','本國','男','O',NULL,NULL,NULL,'0985518388','Colorbliss8868@gmail.com',NULL,'新北市蘆洲中山一路120巷7弄40號','已婚','高中','商',NULL,NULL,'基層醫療',NULL,NULL,'包蕙如','0932027296','員工',NULL,NULL,NULL,NULL,'2025-05-20 14:18:43',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:全身皮紅斑塊反覆 近十年\n現病史:病患自述皮紅斑塊反覆,病灶多發於頭皮、背、四肢、鼠蹊。病灶區色鮮紅,皮損邊緣明顯,有凸起、增厚、脫屑,指甲變形、增厚、甲床剝離、點狀凹陷,曾至皮膚科就診,接受外用類固醇藥膏治療。納可,眠差不易入睡,二便平。風濕科治療,現頭皮屑多,泛紅,手臂紅斑塊大片,後背皮膚紅斑塊厚,頭皮膚紅疹,指甲乾癬,關節稍變形\n2025/05/20 乾癬持續改善,手臂紅斑塊少許 鳞屑 己無,變淡,變平,後背皮膚紅斑塊厚,頭皮紅疹減少,指甲乾癬,關節稍變形,',NULL,'溫清飲 4GM TID*28',NULL,'2025-07-29 02:57:25');
