INSERT INTO `patient` VALUES (687,NULL,NULL,'曹靜文',NULL,'1977-10-18','A224499940','本國','女',NULL,NULL,NULL,NULL,'0918862672','kiki661018@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2018/12/06\n主訴:手脹紅腫脫鱗屑伴隨搔癢超過半年\n現病史:從2018年三月無特別誘發原因,手掌紅腫伴隨搔癢,西醫診斷為濕疹(診所)/類乾癬(臺大,黃-憲診所),照過一次光,現塗抹類固醇,效果不好。現病灶於雙手掌,兩腳側與腳底,紅腫伴隨輕微搔癢,屑偶有膿包。天氣變化症狀加重。右拇指與小指/左手中指剝離伴隨增厚。睡眠偶被搔癢影響,食纳正常。二便正常。\n2025/04/15 手掌皮膚脫皮近惡化,腳底病灶紅斑塊 乾粗燥,粗,脫皮有屑 不規則服藥,輕,腿皮 搔癢減輕,指甲病灶,衛教少碰,用藥,胃嘈雜近未作,右膝關節腫痛,減輕,風濕科治療停止',NULL,'溫清飲 3GM BID*28\n香砂六君子湯 1GM BID*28\n當歸拈痛湯 2GM BID*28\n靈*1',NULL,'2025-06-20 04:09:28');
INSERT INTO `patient` VALUES (688,NULL,NULL,'劉皇良?',NULL,'1990-03-06','M122446663','本國','男',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-21 09:52:06',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑塊十年以上\n現病史:全身皮膚紅斑塊這布,後背,腹病灶厚,縣属厚\n2025/04/11 後頭部病灶紅腫開刀清創,無腫,皮乾燥癢作 頭皮膚乾燥泛紅有屑,糖尿病,飲食衛教,血糖較穩定,手臂乾癬紅斑病灶属厚 手肘紅斑塊大片 衛教運動減重\n2023/09/26 睡不好改善,憂鬱改善,口乾,口渴改善,天氣轉熱,乾響改善,红斑塊病灶位腿,皮庸乾燥,睡眠可,耳後,身體零星病灶\n2025/05/27 天熱,背皮膚乾癬紅斑塊作,減輕 皮膚乾燥不適, 咳嗽輕微 咽有痰梗減少,鼻涕倒流 經常口乾舌燥改善,晚睡,睡少,眼周红疹仍有,鼻塞少,',NULL,NULL,NULL,'2025-06-18 09:05:31');
