INSERT INTO `patient` VALUES (695,NULL,NULL,'徐敏?',NULL,'1955-10-06','C200645148','本國','女',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-21 12:01:26',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:頭皮膚乾癬紅塊作,搔癢作\n現病史:手掌腳掌紅斑塊,易乾裂,頭皮屑多,手指關節腫痛,額皮膚紅斑塊,四肢零星紅斑塊2020/10/20開始治療,手掌皮膚乾裂改善,頭皮,無關節腫痛,甲溝炎,指甲生長異常,,\n近又頭皮癢 頭皮膚紅斑塊多,,額皮膚乾粗,腿皮膚乾燥,後背皮搔抓紅疹大片,乾\n2025/05/20 掌腕關節痛,便秘作有改善,,已無頭皮癢 頭皮紅斑塊多仍有,額皮膚乾粗,腿皮膚乾燥,後背皮膚搔抓紅疹大片,乾燥,已無胃不適,',NULL,'溫清飲 4GM TID*28\n香砂六君子湯 0.5GM TID*28\n桃核承氣湯 0.2GM TID*28',NULL,'2025-06-18 09:18:06');
INSERT INTO `patient` VALUES (696,NULL,NULL,'黃舒楣',NULL,'1986-09-17','B222527746','本國','女',NULL,NULL,NULL,NULL,'0917547997','wynnepatent@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-21 12:05:23',NULL,NULL,NULL,NULL,NULL,NULL,'20240219\n主訴:皮膚炎 紅腫、癢疹、稍脫屑,近2年\n現病史:皮膚炎 自兩年前(2022年)始,先發作於 頭部(後側頭皮~後髮際),現病灶(2024/02/19)於 頭部(後側頭皮~後髮際、雙顳側)、頸部、上肢(雙手上臂甚、前臂稍微)、下肢(雙小腿前方、膝膕窩)、軀幹(胸部、雙側腰部、下背部、胯下、陰毛恥骨聯合處),以額頭 最為嚴重。局部皮膚紅腫&紅疹,色鮮紅,有搔抓傷口,無組織液滲出,皮膚(粗糙、乾燥、稍脫屑)。夜眠因癢甚夜眠差,睡眠中不自覺搔抓、會癢到醒來。曾使用西醫類固醇外用、口服抗組織胺治療,使用後症狀 無明顯改善,停藥後症狀又復發。\n納可,眠差(因搔癢甚)。二便平(大便一日1行,質稍硬、成形,小便正常,尿色稍偏黃)。\n喜肉類(雞肉、魚肉)、蛋、牛奶 會當正餐。吃麵食類,易胃脹,一週2次。',NULL,'溫清飲 2GM TID*28\n香砂六君子湯 1GM TID*28\n黃連解毒湯 1GM TID*28\n普濟消毒飲 2GM TID*28',NULL,'2025-06-13 04:00:42');
