INSERT INTO `patient` VALUES (838,NULL,NULL,'申台煥',NULL,'2014-04-14','N127556709','本國','男',NULL,NULL,NULL,NULL,'0977756558','ashin0217@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-26 13:01:34',NULL,NULL,'牛奶/蛋黃/花生',NULL,NULL,NULL,'20170126\n主訴:皮膚炎自出生3個月發作(加拿大)多倫多\n現病史:病人母親告知自出生3個月,皮膚炎發作於臉部、頸部、手肘、膝膕、手腕足踝、胸腹部、腰背部,以臉部最為嚴重。局部皮膚紅腫,色鲜红,有搔抓傷口,部份滲組織液,搔癢甚,輕微增厚·因癢甚夜眠差,睡眠中不自覺搔抓、不會醒來。IGA(5),Itching score(8), BSA(26%) EASI:17.4·曾使用西醫類固醇、口服抗組織胺治療,效果平。類固醇已停數月·納可·二便平·105/12月於頌華中醫診所接受內服及外用藥後爆發全身红疹',NULL,'0*6',NULL,'2025-06-16 05:16:09');
