INSERT INTO `patient` VALUES (857,NULL,NULL,'蘇琬婷',NULL,'1980-07-18','A224757625','本國','女',NULL,NULL,NULL,NULL,'0918580914','kncpgtv@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-27 09:42:19',NULL,NULL,NULL,NULL,NULL,NULL,'傳統\n\n主訴:頭皮及後頸處皮膚斑塊復發\n現病史:乾癣十多年,治療改善,近頭皮及後頸處皮膚斑塊復發 淡紅色斑塊 頭皮,癢作,鱗屑偏多 後頸搔癢感,,睡眠平,二便平 胃食道逆流,咽喉卡卡有痰感近未作, 後頸皮膚暗紅塊\n2025/05/26 頭皮癢,鱗屑多\n国人史:',NULL,NULL,NULL,'2025-06-13 03:51:55');
INSERT INTO `patient` VALUES (858,'000079474838',NULL,'楊宜潔',NULL,'1980-09-18','H222707124','本國','女',NULL,NULL,NULL,NULL,'0917769733','babyish09180@gmail.com',NULL,'台北市新生北路三段87巷31號4樓',NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-27 09:48:22',NULL,NULL,NULL,NULL,NULL,NULL,'#主訴:四肢及頭皮紅斑塊2年\n現病史:患者兩年前工作壓力大 掉髮多 發現頭皮红斑塊,皮膚科診斷乾癬 接受外用類固醇及抗组織胺治療,但仍反覆發作,曾接受中藥洽療但無改善。目前四肢有1*1公分斑塊數塊 色淡紅 伴輕微脫屑 無凸起 癢,頭皮有7*8公分斑塊 微凸起 鱗屑厚 。無指甲異常 關節無疼痛。天氣變化時易打噴嚏流鼻水 睡覺時易鼻塞 眼睛癢鼻癢。LMP:5/12經痛一日,3-4日量多伴血塊 經期結束前頭痛。眠可(11點入睡)偶失眠。二便平。胃易脹氣喝牛奶及豆漿時加重。每日一杯咖啡,治療後膚紅斑塊改善,鼻塞改善,\n2025/05/27 服中藥,易口乾,稍有減輕,皮膚乾燥作乾眼症,難經治療,仍乾澀,眼周皮膚乾燥,夜間乾醒,點藥油會,胃脹氣作,',NULL,NULL,NULL,'2025-06-30 07:38:40');
INSERT INTO `patient` VALUES (859,NULL,NULL,'李英碩',NULL,'2015-11-30','A133131100','本國','男','O',NULL,NULL,NULL,'0922123117','wangvivian1201@gmail.com',NULL,'台北市中山區長春路258巷27號8樓','未婚','國小','學生',NULL,NULL,'基層醫療',NULL,NULL,'王薏菱','0922123117','母子',NULL,NULL,NULL,NULL,'2025-05-27 09:54:08',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:上唇皮膚乾燥,自去年八月作\n現病史:上唇皮膚乾燥,脫皮,偶癢作\n2025/05/05 游泳後惡化',NULL,NULL,NULL,'2025-07-14 08:57:02');
