INSERT INTO `patient` VALUES (861,NULL,NULL,'洪喻浩',NULL,'2003-09-24','A131704721','本國','男',NULL,NULL,NULL,NULL,'0930234768','apple987654378@yahoo.com.tw',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-27 09:57:12',NULL,NULL,NULL,NULL,NULL,NULL,'20181015\n主訴:皮膚起紅色搔癢丘疹多年\n現病史:自小有AD病史,症狀反覆發作。近一年(国三)症狀加重,現病灶於面部(臉頰/耳),頸部,軀幹與四肢起红色搔癢丘疹伴隨脫屑與輕微苔癬化,搔抓後血痕與組織液。以耳朵,頸部症狀最重,無特別誘發與加重因子。塗抹類固醇與口服抗組織胺症狀反覆發作,因搔癢影響睡眠,食慾可,二便正常。',NULL,NULL,NULL,'2025-05-27 02:21:29');
