INSERT INTO `patient` VALUES (865,'000074250519',NULL,'楊乙桓',NULL,'2016-03-14','F133746937','本國','男',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-27 10:07:46',NULL,NULL,'塵螨',NULL,NULL,NULL,'主訴:雙下肢、右手背紅疹發癢约半年。\n現病史:皮膚炎自2023年初發作,發作於雙側小腿,漸及雙側大腿、手背、前臂,以雙側小腿最為嚴重。局部皮膚紅疹,色暗紅,有搔抓傷口,無組織液滲出,皮膚粗糙乾燥、增厚。因癢甚夜眠差,睡眠中不自覺搔抓、會因癢而醒來。曾至西醫小兒科就診,診斷為異位性皮炎,曾使用西醫類固醇外用、口服抗組織胺治療,使用後症狀改善,停藥後症狀又復發。\n納可。二便平。\n2025/05/26 腿皮膚搔抓丘疹多',NULL,NULL,NULL,'2025-07-17 10:57:54');
