INSERT INTO `patient` VALUES (936,NULL,NULL,'王觀紓',NULL,'1992-02-18','F227952172','本國','女','A',NULL,'0910113370',NULL,'0918106347','wing81218@yahoo.com.tw',NULL,'新北市新店區永業路81巷3弄23號2樓','未婚','碩士','補教業',NULL,NULL,'基層醫療',NULL,NULL,'張慧萍','0910113730','母女',NULL,NULL,NULL,NULL,'2025-05-27 12:28:14',NULL,NULL,NULL,NULL,NULL,NULL,'2019/08/20\n主訴:後頸乾癬反復\n現病史:病患自訴下腹抽痛已1年,曾至婦產科,接受超音波檢查,巧克力囊腫5cm,子宮肌腺瘤(2個,2cm,2cm),月經量中,血塊(约十元硬幣大小)痛經 經色鲜紅。納可,眠可, 小便平,大便(一日1-2行腹瀉便秘交替)。下巴痤瘡作,近下腹常抽痛\n2025/05/27 經痛稍有減輕,後枕頭頸皮膚紅斑塊持平,肩頸,腹部腰際,大腿皮膚癢,新長红疹,天冷易作 睡前服中藥胃痛作,,睡9PM-3AM少,下腹抽痛1-2作/週(ovary cysts)已\n少,晨起胃痛減輕 較晚吃飯,胃食逆流反復,檢查有食道癌前病變,衛教飲食,晚睡',NULL,NULL,NULL,'2025-07-09 01:06:37');
INSERT INTO `patient` VALUES (937,'000054038000',NULL,'楊喆宇',NULL,'1992-10-31','C121433057','本國','男','O',NULL,NULL,NULL,'0978527786','Kevin20031125@hotmail.com',NULL,'台北市內湖區康寧路3段103—1號6樓','未婚','碩士','工',NULL,NULL,'基層醫療',NULL,NULL,'洪永凌','0911960536','母',NULL,NULL,NULL,NULL,'2025-05-27 12:28:39',NULL,NULL,NULL,NULL,NULL,NULL,'2021/11/09\n主訴:頭皮皮膚紅斑塊反覆已7年\n現病史:病患自述頭皮皮膚紅斑塊反覆已7年,病灶區位於頭皮、腋下、鼻樑旁,病灶區:皮膚色鮮紅,病灶邊缘明顯,皮膚增厚,鳞屑平,癢感微,水泡無,搔抓無滲   異狀,關節活動正常,曾至皮膚科就診,診斷為乾癬,曾接受外用類固醇藥膏,但停藥後症狀反覆難癒。納可、眠可、二便可。\n2025/05/27 枕後頭皮紅斑塊有改善,紅疹零星減少,腳大趾背斑塊厚,腿皮癢減少,頭皮膚 泛紅不明顯,少屑,少服藥,衛教勿服甜食',NULL,NULL,NULL,'2025-11-25 01:42:08');
