INSERT INTO `patient` VALUES (1008,'000010530735',NULL,'許毓峰',NULL,'1973-10-09','S120298922','本國','男','B',NULL,NULL,NULL,'0933872924','yfs1009@gmail.com',NULL,'新北市淡水區新興街123號','已婚','碩士','軍公教',NULL,NULL,'基層醫療',NULL,NULL,'許詠雋','0966707766','父子',NULL,NULL,NULL,NULL,'2025-05-28 09:23:52',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:皮膚濕疹發作二年\n現病史:自打疫苗後,皮膚癢疹作,手肘內,手臂,腿窩搔抓苔蘚化粗,身體红疹塊大片,小腿後皮膚紅腫,結痂,\n2025/05/27 晚睡,皮膚炎未有明顯改善,皮膚差,胃不適少作',NULL,NULL,NULL,'2025-07-22 02:21:35');
INSERT INTO `patient` VALUES (1009,NULL,NULL,'李錫明',NULL,'1970-10-08','A123312059','本國','男','O',NULL,NULL,NULL,'0935659262',NULL,NULL,'新北市汐止區建成路57巷40號11樓','已婚','專科','商',NULL,NULL,'基層醫療',NULL,NULL,'吳佩姬','0930003629','夫妻',NULL,NULL,NULL,NULL,'2025-05-28 10:17:13',NULL,NULL,NULL,NULL,NULL,NULL,'2021/01/19\n主訴:皮膚乾癬紅斑塊復作\n現病史:乾癬20年以上,頭皮/身體,外院中西皆有治療過(國泰 照光/外用類固醇,無處方中華,速效),\n五年前本院治療改善,,近三個月復發,BSA>60%,小腿皮膚病灶乾燥,會胃脹,胃道逆流,指關節痛少作,指甲變形,頭皮屑多\n2025/05/27近持平,頭皮屑 天氣變冷時增多,頭皮皮膚 病 乾燥泛紅,小腿皮膚澱粉沈著,乾,癢,右手指關節腫痛偶作,衛教多飲水,配合運動. \n手肘,手臂,紅斑塊癢疹乾燥,額有紅斑塊,夜鼻塞近有減輕,鼻涕倒流.上夜班加重',NULL,NULL,NULL,'2025-07-22 04:00:46');
INSERT INTO `patient` VALUES (1010,NULL,NULL,'高淑文',NULL,'1960-04-24','F220006695','本國','女','A',NULL,NULL,NULL,'0912552998',NULL,NULL,'台北市信義區永吉路180巷70弄20號3樓','已婚','高中','家管',NULL,NULL,'基層醫療',NULL,NULL,'吳文宏','0919259904','夫妻',NULL,NULL,NULL,NULL,'2025-05-28 10:28:21',NULL,NULL,NULL,NULL,NULL,NULL,'主訴 : 腿皮膚紅斑塊反復,\n現病史:乾癬近20年 病灶位 頭皮,背,胸,腹,手肘,手臂,大腿,膝,小腿,指甲\n頭皮屑少,恐慌 開刀後造成乾癬 紅疹 小腿乾癬斑點狀分布,皮膚會癢,耳內癢\n2025//05/27腿皮膚紅斑塊零星,.胃痛,胃泛酸作改善,仍心慌作,手指背關節皮膚暗沈,厚,肛裂出血已無,大便不順改善,膝關節復建中,潮熱近減少作,',NULL,NULL,NULL,'2025-07-22 01:12:29');
INSERT INTO `patient` VALUES (1011,'000004497295',NULL,'張慧萍',NULL,'1974-02-10','T220664750','本國','女','O',NULL,NULL,NULL,'0910113730','shelly0015@yahoo.om.tw',NULL,'新北市新店區美城里永業路81巷3弄23號2樓','已婚','大學','家管',NULL,NULL,'基層醫療',NULL,NULL,'王觀紓','0918106347','母女',NULL,NULL,NULL,NULL,'2025-05-28 10:44:27',NULL,NULL,NULL,NULL,NULL,NULL,'2019/01/14\n主訴:全身膨疹發作 反覆已2年\n現病史:病患自述全身皮膚,病灶多發於四肢,服西藥2-4天發一次。病灶區微鮮紅膨疹線條狀,皮劃紋症發作後4小時消失,乾燥,曾至皮膚科就診,診斷為膨疹,接受外用類固醇藥膏、口服抗組織胺治療,症狀緩解。納可,眠可,二便平。\n2025/04/15 手臂皮膚癢作,睡前和晨起易咳嗽作,白痰多,咽癢,蕁麻疹夜間發 皮膚癢,少有打噴嚏,咳喘腿濕疹偶發,脖頸,,睡眠可',NULL,NULL,NULL,'2025-11-26 08:41:24');
INSERT INTO `patient` VALUES (1012,'000088973836',NULL,'王瑩宏',NULL,'1966-11-13','Q120793840','本國','男','A',NULL,NULL,NULL,'0936261631',NULL,NULL,'新北市新店區永業路81巷3弄23號2樓','已婚','高中','工',NULL,NULL,'基層醫療',NULL,NULL,'張慧萍','0910113730','夫妻',NULL,NULL,NULL,NULL,'2025-05-28 10:48:54',NULL,NULL,NULL,NULL,NULL,NULL,'2019/01/14\n主訴:全身皮膚红斑塊反覆 逾4年\n現病史:病患自述皮膚红斑塊反覆逾4年,以大腿最為嚴重。病灶區色鲜紅,皮損邊缘明顯,有凸起、增厚、苔蘚化、脫屑、色素沈積、粗乾,指甲變形、增厚、甲床剝離、點狀凹陷,\n無關節伸屈不利,曾接受外用類固醇藥膏、口服藥治療,停藥後症狀反覆。纳可,眠可,二便平。\n2025/05/27 手臂皮膚紅斑塊 右小腿红斑塊大片,乾燥有屑,左腿零星,頭皮屑多,衛教用藥方法,膝關節退化,膝腿皮開刀,後枕頭皮癢 腰腹部皮膚紅斑塊,指甲生長異常改善,胃痛,胃泛酸作飲食衛教,改善,偶發作,',NULL,NULL,NULL,'2025-10-28 01:59:30');
INSERT INTO `patient` VALUES (1013,'000088763816',NULL,'吳峻次',NULL,'1995-01-26','F129356649','本國','男','B',NULL,NULL,NULL,'0938333766','t102360455@gmail.com',NULL,'新北市樹林區國凱街50巷30號3樓','未婚','大學','工',NULL,NULL,'基層醫療',NULL,NULL,'蔡綉菊','0983087879','母子',NULL,NULL,NULL,NULL,'2025-05-28 11:02:46',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:自國三起乾癣發作\n現病史:自國三起乾癬發作,現腹部和頭皮膚紅斑塊厚,大片,腳少許\n2025/05/27 腹部紅斑塊,早起變淡,後背皮膚新長病灶作減少,皮膚病灶泛紅,乾燥,頭皮膚發紅,乾燥屑多,毛囊炎腫痛,天熱流汗 近未作,體重110減至80多公斤,晚睡>11,,再次衛\n教飲食',NULL,NULL,NULL,'2025-08-11 06:59:50');
INSERT INTO `patient` VALUES (1014,NULL,NULL,'蔡宜均',NULL,'2005-09-11','G222512642','本國','女',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-28 11:22:34',NULL,NULL,NULL,NULL,NULL,NULL,'2024/11/01\n主訴:大腿內側癢疹反覆四至五年\n病患自述大腿內側疹反覆發作四至五年,近期因天氣炎熱和工作繁忙,出汗多,搔癢加劇。病灶分布於雙腿內外側,呈現暗紅色丘疹伴隨抓搔破皮舆結痂,偶有组織液,病灶邊緣不\n明顯。過去食用海鲜加重。手肘內、上臂外側、右側脖頸已無紅疹,有輕微色素沉澱。近期自覺口乾舌燥,汗多,食慾減少,難入睡;大便一日一至二行,成形,小便可。\n月經不規則,初經為11歲,月經還期1-3個月不等,伴隨腹痛、疲倦,經血色深量多。\n20250527 後頸頭皮癢疹,稍有減輕,丘疹,貼膏藥過敏_手肘外側,乾燥,脫皮,大腿內側癢疹,泛紅減輕,天熱作',NULL,NULL,NULL,'2025-05-28 03:26:57');
INSERT INTO `patient` VALUES (1015,NULL,NULL,'蔡惠如',NULL,'1978-05-22','E222694521','本國','女','B',NULL,NULL,NULL,'0979155522',NULL,NULL,'新北市中和區景平路431巷96號8樓','單身','大學','自由業',NULL,NULL,'基層醫療',NULL,NULL,'甘子葳','0979209179','友',NULL,NULL,NULL,NULL,'2025-05-28 11:29:53',NULL,NULL,NULL,NULL,NULL,NULL,'2019/01/24\n主訴:頭部、顏面皮膚紅斑塊 反覆逾二年\n現病史:病患自述皮膚紅斑塊反覆逾2年,病灶發於頭皮、顏面、耳頸項後、右腰,以項後最為嚴重。病灶區色鲜红,皮損邊缘明顯,凸起、粗糙、增厚、苔癬化、脫屑,2年前曾至皮\n膚科接/外用類固醇藥膏治療。納可,眠可,二便平\n2025/05/27天熱改善,身體皮膚 長乾癣病灶改善,皮膚乾燥,頭皮減輕,額有紅斑塊,指甲乾癬治療緩慢,衛教少碰水,載手套,指甲乾癬改善,項皮膚起红斑塊大片變淡中,耳後新長红斑塊,手臂肘新红疹塊減少',NULL,NULL,NULL,'2025-10-18 06:48:48');
