INSERT INTO `patient` VALUES (1027,'000050218559',NULL,'危妍潔',NULL,'2003-05-13','A230729397','本國','女','B',NULL,NULL,NULL,'0975180253','wei.chieh0513@gmail.com',NULL,'新北市林口區公園路15號5樓','未婚','大學','學生',NULL,NULL,'基層醫療',NULL,NULL,'陳曉琦','0916190898','母女',NULL,NULL,NULL,NULL,'2025-05-29 16:52:33',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:手肘內皮膚癢搔抓\n現病史:手肘皮膚乾燥,暗沈癢搔抓,手指皮膚泛红乾燥,腳足背,後頸也有,眼癢,流鼻水反復\n2025/05/28 膕窩,乾燥有屑癢作,手臂內側乾粗,手肘內皮膚红明顯作,手肘內洗澡後,皮膚癢作 左手腕皮膚炎红腫已無,少红疹,,衛教衣著,少敷藥水,皮膚癢作,冷皮膚乾燥,熱水洗後癢,腹部皮膚癢減輕,手指皮膚指缝 乾燥持平,脖頸,手部皮膚仍乾燥有屑,眼周红減輕,流鼻水己無',NULL,'消風散 3GM TID*28\n甘麥大棗湯 0.5GM TID*28\n溫清飲 2GM TID*28\n桂枝龍骨牡蠣湯 0.5GM TID*28',NULL,'2025-07-31 08:48:35');
INSERT INTO `patient` VALUES (1028,NULL,NULL,'邱國達',NULL,'1966-01-20','K120055056','本國','男',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-29 17:01:56',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:皮膚紅斑塊约五年\n現病史:乾癬發作五年,曾使用牛樟芝加重,中藥加重,現全身遍布,血壓稍高,肝功能異常\n2025/05/28 胃食道逆流惡化改善,咖啡 飲用,心悸惡化,手肘病灶新長,指甲溝炎惡化,衛教少 碰水,小腿脛前皮膚红斑塊 衛教包敷,皮膚乾燥癢 衛教保濕, 高血壓未服西藥,睡不好 夜間三點醒 腹側红疹塊改善,膝蓋退化性關節炎',NULL,'香砂六君子湯 3GM TID*30\n天王補心丹 3GM HS*30\n柴胡加龍骨牡蠣湯 2GM HS*30\n養心湯 1GM HS*30\n黃連 0.4GM HS*30\n平胃散 1.2GM HS*30\n海螵蛸 0.5GM HS*30\n龜鹿二仙膠濃縮丸 2PC BID*30',NULL,'2025-06-16 05:34:32');
