INSERT INTO `patient` VALUES (1046,NULL,NULL,'馬懿揚',NULL,'2017-12-12','A132915577','本國','男',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-06-06 15:54:44',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:雙眼红腫、全身紅色癢疹\n現病史:皮膚炎自出生2-3個月大時出現,發作於手肘、手腕及耳後,曾經接受類固醇外用治療1周前於飯店住宿後開始出現全身癢疹,3天前搔癢感加劇,出現雙上瞼皮紅腫及全身紅色癢疹, 夜間甚,影響睡眠,服用anti-histamin後可缓解。纳可。大便日1行,成形易解,小便平。\n250527胸前癢疹作',NULL,'三*4\n皮*4',NULL,'2025-06-16 05:25:57');
