INSERT INTO `patient` VALUES (1049,NULL,NULL,'徐順耘',NULL,'2017-09-01','A133483378','本國','男',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-06-06 16:03:54',NULL,NULL,NULL,NULL,NULL,NULL,'2018/01/16\n主訴:皮膚炎自出生1個月發作\n現病史:患者自出生即發現頭皮脂漏性皮膚炎,後發現臉部紅疹及丘疹伴搔抓及组織液滲出,小兒科診斷脂漏性皮膚炎,接受外用類固醇後能改善 但停藥後復發。目前,腳踝、膝窩、\n頭部、紅腫半红疹,小腿及腳板皮膚粗糙顆粒感。有搔抓傷口,無組織液滲出。夜眠可不會醒來 但入睡困難。曾使用西醫類固醇外用、口服抗組織胺治療。納可。二便平。',NULL,NULL,NULL,'2025-06-06 08:05:36');
