INSERT INTO `patient` VALUES (1051,NULL,NULL,'李穆昀',NULL,'2018-01-31','F233786237','本國','女',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-06-06 16:09:13',NULL,NULL,NULL,NULL,NULL,NULL,'2019/07/09\n主訴:全身皮膚红疹搔抓\n現病史:皮膚炎自出生6個月發作,發作於頭部(臉部/頭皮/耳後)、頭部、上肢(手肘/手腕)、下肢(大小腿/膝膕窩/足踝)、軀幹(胸腹部/腰背部),全身皮膚红疹搔抓, 因癢甚夜眠差,睡眠中不自覺搔抓。現膕窩搔抓仍有。納可。二便平。\n2024/02/01 臉鼻側紅疹少許 耳裂紅疹 無,皮膚微乾,搔抓少,鼻孔癢.打噴嚏\n手腕皮膚搔抓红疹\n',NULL,NULL,NULL,'2025-06-06 08:20:24');
