INSERT INTO `patient` VALUES (1054,NULL,NULL,'葉于台',NULL,'1956-09-12','F103734250','本國','男',NULL,NULL,NULL,NULL,'0932030785','Sophyyeh@hotmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-06-06 16:25:33',NULL,NULL,NULL,NULL,NULL,NULL,'2022/08/18\n主訴:1.頭皮、脫屑3個月:2泛酸、灼熱偶作\n現病史:頭皮癢、頭皮屑多3個月,皮膚科外用藥膏治療效差。\n目前頭皮红,搔癢嚴重,撥頭髮時頭皮屑多,頭頂淡红斑塊、脫屑,四肢乾燥疹塊偶作,無搔癢,會自行消失。眠平。二便平\n2025/05/29 咳嗽數月,有痰',NULL,'清肺湯 3GM TID*28\n小柴胡湯(甲) 2GM TID*28',NULL,'2025-06-09 08:48:11');
