INSERT INTO `patient` VALUES (1061,NULL,NULL,'朱拓安',NULL,'2015-12-29','A170142103','本國','男',NULL,NULL,NULL,NULL,'0927931037','jlchu0705@gmail.com',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'基層醫療',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-06-06 16:46:24',NULL,NULL,NULL,NULL,NULL,NULL,'主訴:四肢皺褶處和上背部局部皮膚粗糙乾燥 一年多\n現病史:皮膚炎自出生一歲起發作,發作於頭部、手肘、手腕、大小腿、膝膕窩、足踝、腹部、鼠蹊部和上背部,以上背部最為嚴重。局部皮膚紅腫起紅疹,色暗紅,有搔抓傷口,無\n組織液滲出,皮膚粗糙乾燥。夜眠因甚夜眠差,睡眠中不自覺搔抓、近一個月約AM2:00會醒來。半年前起自診所看診,使用西醫類固醇外用、口服抗組織胺治療,使用後症狀改\n善,但病情反覆,現僅抹乳液保濕,嚴重時才會擦藥膏。纳平,挑食。排便2-3日一行,偏硬,肛門有傷口。\n2025/05/29 後背上方搔抓,膕窩红疹,微红,不粗,',NULL,'皮*6\n0*4\n三',NULL,'2025-06-16 05:33:46');
